import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'
import { TanStackRouterVite } from '@tanstack/router-plugin/vite'

// https://vite.dev/config/
export default defineConfig({
  plugins: [TanStackRouterVite({ target: 'react' }), react()],
  server: {
    port: 4273,
  },
})

import { Outlet, createRootRouteWithContext } from '@tanstack/react-router'
import { NavigationMenu } from '../components/NavigationMenu'

export const Route = createRootRouteWithContext()({
  component: RootComponent,
})

function RootComponent() {
  return (
    <div className="app-shell">
      <NavigationMenu />
      <main className="app-main">
        <Outlet />
      </main>
    </div>
  )
}

import { createFileRoute } from '@tanstack/react-router'

export const Route = createFileRoute('/')({
  component: HomeComponent,
})

function HomeComponent() {
  return (
    <section className="page">
      <h1>Home</h1>
      <p>
        Welcome to the home page. This is a type-safe navigation demo built with
        TanStack Router.
      </p>
    </section>
  )
}

import { createFileRoute } from '@tanstack/react-router'

export const Route = createFileRoute('/about')({
  component: AboutComponent,
})

function AboutComponent() {
  return (
    <section className="page">
      <h1>About</h1>
      <p>
        This page demonstrates file-based routing with TanStack Router. Each
        route is a separate file under <code>src/routes</code>.
      </p>
    </section>
  )
}

import { createFileRoute } from '@tanstack/react-router'

export const Route = createFileRoute('/contact')({
  component: ContactComponent,
})

function ContactComponent() {
  return (
    <section className="page">
      <h1>Contact</h1>
      <p>
        You can reach us at{' '}
        <a href="mailto:hello@example.com">hello@example.com</a>.
      </p>
    </section>
  )
}

import { StrictMode } from 'react'
import { createRoot } from 'react-dom/client'
import { RouterProvider, createRouter } from '@tanstack/react-router'
import { routeTree } from './routeTree.gen'
import './index.css'

const router = createRouter({ routeTree })

declare module '@tanstack/react-router' {
  interface Register {
    router: typeof router
  }
}

createRoot(document.getElementById('root')!).render(
  <StrictMode>
    <RouterProvider router={router} />
  </StrictMode>,
)

